{"command":"cat << 'EOF' > test_ping.go
package main

import (
	"fmt"
	"net"
	"syscall"
	"time"
)

func main() {
	fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	if err != nil {
		fmt.Println("Socket error:", err)
		return
	}
	defer syscall.Close(fd)

	fmt.Println("Socket created successfully!")

	// Create a simple ICMP Echo Request
	// Type: 8, Code: 0, Checksum: 0, Id: 1, Seq: 1
	packet := []byte{8, 0, 0, 0, 0, 1, 0, 1}

	// Calculate checksum
	var sum uint32
	for i := 0; i < len(packet); i += 2 {
		sum += uint32(packet[i])<<8 | uint32(packet[i+1])
	}
	sum = (sum >> 16) + (sum & 0xffff)
	sum = sum + (sum >> 16)
	checksum := ^uint16(sum)
	packet[2] = byte(checksum >> 8)
	packet[3] = byte(checksum)

	addr := syscall.SockaddrInet4{Port: 0}
	copy(addr.Addr[:], net.ParseIP("127.0.0.1").To4())

	err = syscall.Sendto(fd, packet, 0, &addr)
	if err != nil {
		fmt.Println("Sendto error:", err)
		return
	}

	fmt.Println("Packet sent!")

	buf := make([]byte, 1024)
	syscall.SetNonblock(fd, false)
	n, _, err := syscall.Recvfrom(fd, buf, 0)
	if err != nil {
		fmt.Println("Recvfrom error:", err)
		return
	}
	fmt.Printf("Received %d bytes: %v\n", n, buf[:n])
}
EOF
go run test_ping.go
"}

